import json,sys
from playwright.sync_api import sync_playwright
R=[];ok=lambda n,c,d='':(R.append((n,bool(c),d)),print(('PASS ' if c else 'FAIL ')+n+(' — '+str(d) if d and not c else '')))
URL='file:///tmp/site.html'
def block(route):
    u=route.request.url
    route.abort() if not u.startswith('file://') else route.continue_()
with sync_playwright() as p:
    b=p.chromium.launch()
    ctx=b.new_context(viewport={'width':1440,'height':900});pg=ctx.new_page();errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)));pg.route('**/*',block)
    pg.goto(URL);pg.wait_for_timeout(2600)
    # ---- cursor
    ok('old #cur square removed',pg.query_selector('#cur') is None)
    ok('native cursor NOT hidden before any mouse move',pg.evaluate("!document.documentElement.classList.contains('tn-cur')"))
    pg.mouse.move(400,300);pg.wait_for_timeout(120)
    st=lambda:pg.evaluate("document.querySelector('#cx').dataset.s||'arrow'")
    ok('custom cursor enabled after real mouse move',pg.evaluate("document.documentElement.classList.contains('tn-cur')&&document.querySelector('#cx').matches(':popover-open')"))
    ok('native cursor hidden only now',pg.evaluate("getComputedStyle(document.body).cursor")=='none')
    box=pg.evaluate("(()=>{const r=document.querySelector('#cx svg.a').getBoundingClientRect();return[r.left,r.top]})()")
    ok('arrow tip aligned with pointer (±2px)',abs(box[0]+6-400)<=2 and abs(box[1]+5-300)<=2,box)
    pg.mouse.move(700,640)
    pg.mouse.move(700,641);ok('default state is arrow',st() in('arrow',))
    bx=pg.eval_on_selector('#c1','e=>{const r=e.getBoundingClientRect();return[r.left+r.width/2,r.top+r.height/2]}')
    pg.mouse.move(*bx);pg.wait_for_timeout(300);ok('hover on button → hand state',st()=='hand',st())
    pg.mouse.down();ok('pointer-down → click sparkle',st()=='click',st());pg.mouse.up();pg.wait_for_timeout(300)
    pg.evaluate("document.querySelector('#cb').setAttribute('aria-disabled','true')")
    pg.evaluate("document.querySelector('#fm').scrollIntoView({block:'center',behavior:'instant'})");pg.wait_for_timeout(2600)
    ib=pg.eval_on_selector('#n','e=>{const r=e.getBoundingClientRect();return[r.left+30,r.top+r.height/2]}')
    pg.mouse.move(*ib);pg.wait_for_timeout(100);ok('over text input → I-beam',st()=='text',st())
    cb=pg.eval_on_selector('#cb','e=>{const r=e.getBoundingClientRect();return[r.left+r.width/2,r.top+r.height/2]}')
    pg.mouse.move(*cb);pg.wait_for_timeout(100);ok('over disabled control → prohibited',st()=='no',st())
    pg.evaluate("document.documentElement.classList.add('busy')");pg.wait_for_timeout(100);ok('busy/submitting → spinner',st()=='load',st());pg.evaluate("document.documentElement.classList.remove('busy')")
    sb=pg.eval_on_selector('#t','e=>{const r=e.getBoundingClientRect();return[r.left+30,r.top+r.height/2]}');pg.mouse.move(*sb);pg.wait_for_timeout(100);ok('over <select> → custom cursor off (native popup safe)',st()=='off',st())
    # ---- typing / native editing still works
    pg.click('#n');pg.keyboard.type('Ada Lovelace');ok('typing in inputs works',pg.input_value('#n')=='Ada Lovelace')
    # ---- magnet limit + click accuracy
    pg.evaluate("scrollTo({top:0,behavior:'instant'})");pg.wait_for_timeout(500)
    bx=pg.eval_on_selector('#c1','e=>{const r=e.getBoundingClientRect();return[r.left+r.width-4,r.top+r.height/2]}');pg.mouse.move(bx[0]-90,bx[1]);pg.mouse.move(*bx,steps=6);pg.wait_for_timeout(250)
    tx=pg.evaluate("parseFloat(document.querySelector('#c1').style.getPropertyValue('--tx')||0)");ok('magnet movement limited to ≤6px',abs(tx)<=6,tx)
    pg.mouse.click(*bx);pg.wait_for_timeout(500);ok('click on magnetised CTA still lands (#c1 → #contact)',pg.evaluate("location.hash")=='#contact',pg.evaluate("location.hash"))
    # ---- project dialog with cursor above it
    pg.evaluate("document.querySelector('#proj').scrollIntoView({block:'center',behavior:'instant'})");pg.wait_for_timeout(1800)
    pg.click('#proj .win .btn:has-text("Details")');pg.wait_for_timeout(300)
    ok('project dialog opens',pg.evaluate("document.querySelectorAll('dialog[open]').length")==1)
    pg.mouse.move(720,300);pg.wait_for_timeout(250);pg.screenshot(path='/tmp/dialog.png',clip={'x':660,'y':250,'width':120,'height':100})
    from PIL import Image;im=Image.open('/tmp/dialog.png').convert('L');mx=max(im.getdata())
    ok('custom cursor renders ABOVE the modal dialog (top layer)',mx>180,'max luma %d'%mx)
    pg.keyboard.press('Escape');pg.wait_for_timeout(200)
    # ---- command palette
    pg.mouse.move(300,200);pg.keyboard.press('Control+k');pg.wait_for_timeout(350)
    ok('Ctrl+K opens palette & focuses input',pg.evaluate("document.querySelector('#cp').open&&document.activeElement.id==='cpi'"))
    ok('background scroll locked while open',pg.evaluate("document.documentElement.style.overflow")=='hidden')
    pg.keyboard.type('work');pg.wait_for_timeout(100)
    ok('search filters commands',pg.evaluate("[...document.querySelectorAll('#cpl li b')].map(b=>b.textContent)").__contains__('Go to Work'))
    pg.keyboard.press('Enter');pg.wait_for_timeout(1200)
    ok('Enter runs command (scrolled to Work, palette closed)',pg.evaluate("!document.querySelector('#cp').open&&location.hash")=='#work',pg.evaluate("location.hash"))
    pg.keyboard.press('Control+k');pg.wait_for_timeout(300);pg.keyboard.type('zzzzq');ok('empty state shown',pg.evaluate("document.querySelector('#cpl .none')!==null"))
    pg.keyboard.press('Escape');pg.wait_for_timeout(350);ok('Escape closes + unlocks scroll',pg.evaluate("!document.querySelector('#cp').open&&document.documentElement.style.overflow===''"))
    pg.keyboard.press('Control+k');pg.wait_for_timeout(300);pg.keyboard.type('marvel');pg.keyboard.press('ArrowDown');pg.keyboard.press('ArrowUp');pg.keyboard.press('Enter');pg.wait_for_timeout(500)
    ok('project search opens project dialog',pg.evaluate("document.querySelectorAll('dialog[open]').length")==1 and 'MARVEL' in pg.evaluate("document.querySelector('dialog[aria-label=\"Project details\"] h3').textContent").upper())
    pg.keyboard.press('Escape');pg.wait_for_timeout(200)
    pg.keyboard.press('Control+k');pg.wait_for_timeout(300);pg.keyboard.type('theme');pg.keyboard.press('Enter');pg.wait_for_timeout(600)
    ok('palette toggles theme',pg.evaluate("document.documentElement.dataset.theme")=='light')
    pg.evaluate("document.querySelector('#tt').click()");pg.wait_for_timeout(500);ok('theme button toggles back',pg.evaluate("document.documentElement.dataset.theme")=='dark')
    pg.evaluate("document.querySelector('#fm').scrollIntoView({block:'center',behavior:'instant'})");pg.wait_for_timeout(300);pg.click('#ds');pg.keyboard.press('Control+k');pg.wait_for_timeout(300)
    ok('Ctrl+K NOT hijacked inside a textarea',pg.evaluate("!document.querySelector('#cp').open"))
    pg.evaluate("document.activeElement.blur()");pg.click('#kb');pg.wait_for_timeout(300);ok('header ⌕ button opens palette',pg.evaluate("document.querySelector('#cp').open"));pg.mouse.click(30,30);pg.wait_for_timeout(350)
    ok('backdrop click closes palette',pg.evaluate("!document.querySelector('#cp').open"))
    ok('focus restored after close',pg.evaluate("document.activeElement!==document.body"))
    # ---- hero + reveal motion
    pg.evaluate("scrollTo({top:0,behavior:'instant'})");pg.wait_for_timeout(300)
    ok('hero heading split into words, keeps accessible name',pg.evaluate("document.querySelectorAll('#hb .w').length>0&&document.querySelector('#hb').getAttribute('aria-label').length>0"))
    ok('hero text visible after sequence',pg.evaluate("[...document.querySelectorAll('#hp,#hh,#eb')].every(e=>getComputedStyle(e).opacity==='1')"))
    ok('page has no horizontal overflow',pg.evaluate("document.documentElement.scrollWidth<=innerWidth"))
    pg.screenshot(path='/tmp/hero.png')
    ok('no uncaught JS errors',not errs,errs)
    # ---- touch device: no custom cursor
    t=b.new_context(viewport={'width':390,'height':844},has_touch=True,is_mobile=True);tp=t.new_page();terr=[];tp.on('pageerror',lambda e:terr.append(str(e)));tp.route('**/*',block);tp.goto(URL);tp.wait_for_timeout(2600)
    tp.touchscreen.tap(200,400);ok('touch: native cursor untouched, no custom cursor',tp.evaluate("!document.documentElement.classList.contains('tn-cur')"))
    tp.click('#mb');tp.wait_for_timeout(400);ok('mobile menu opens (aria-expanded)',tp.get_attribute('#mb','aria-expanded')=='true')
    ok('mobile: no horizontal overflow',tp.evaluate("document.documentElement.scrollWidth<=innerWidth"),tp.evaluate("document.documentElement.scrollWidth"))
    tp.screenshot(path='/tmp/mobile.png');ok('mobile: no JS errors',not terr,terr)
    # ---- reduced motion: everything visible immediately
    rm=b.new_context(viewport={'width':1280,'height':800},reduced_motion='reduce');rp=rm.new_page();rp.route('**/*',block);rp.goto(URL);rp.wait_for_timeout(800)
    ok('reduced motion: below-fold content visible without animation',rp.evaluate("[...document.querySelectorAll('#fm,#tiers>.win,.tl>li')].every(e=>getComputedStyle(e).opacity==='1')"))
    # ---- scroll reveals (normal motion): hidden until reached
    n=ctx.new_page();n.route('**/*',block);n.goto(URL);n.wait_for_timeout(2200)
    h=n.evaluate("getComputedStyle(document.querySelector('#fm')).opacity");n.evaluate("document.querySelector('#fm').scrollIntoView({block:'center',behavior:'instant'})");n.wait_for_timeout(1700)
    ok('scroll reveal: form hidden below fold, revealed on arrival',h=='0' and n.evaluate("getComputedStyle(document.querySelector('#fm')).opacity")=='1',h)
    b.close()
print('\n%d/%d passed'%(sum(1 for r in R if r[1]),len(R)))
